DECLARE v_prev_hash text;v_prev_seq bigint;armed boolean;
BEGIN
 IF p_try THEN
  IF NOT pg_try_advisory_xact_lock(hashtext('audit-chain:'||p_tenant::text)) THEN
   RAISE EXCEPTION 'Audit chain busy' USING ERRCODE='55P03';END IF;
 ELSE PERFORM pg_advisory_xact_lock(hashtext('audit-chain:'||p_tenant::text));END IF;
 SELECT chain_seq,hash INTO v_prev_seq,v_prev_hash FROM public.domain_event
  WHERE tenant_id=p_tenant AND chain_seq IS NOT NULL ORDER BY chain_seq DESC LIMIT 1;
 armed:=current_setting('app.audit_hash_chain',true) IS NOT DISTINCT FROM 'on' OR v_prev_seq IS NOT NULL
  OR EXISTS(SELECT 1 FROM public.tenant_setting WHERE tenant_id=p_tenant AND key='audit.hash_chain_enabled' AND value='true'::jsonb);
 RETURN jsonb_build_object('armed',armed,'priorSeq',v_prev_seq,'priorHash',v_prev_hash);
END

DECLARE prior_seq bigint;prior_hash text;n bigint;selected_n bigint;
BEGIN
 -- VOLATILE fresh snapshots include this command's own INSERT and peer rows. A qualified
 -- composite must actually be the persisted selected event, never an arbitrary supplied tuple.
 IF NOT EXISTS(SELECT 1 FROM public.domain_event e WHERE e.id=p_event.id AND e.tenant_id=p_event.tenant_id
  AND to_jsonb(e) IS NOT DISTINCT FROM to_jsonb(p_event)) THEN RETURN NULL;END IF;
 IF p_event.chain_seq IS NULL THEN
  IF p_event.prev_hash IS NOT NULL OR p_event.hash IS NOT NULL THEN RETURN NULL;END IF;
  RETURN jsonb_build_object('armed',false,'priorSeq',NULL,'priorHash',NULL);
 END IF;
 IF p_event.chain_seq<1 OR p_event.prev_hash IS NULL OR p_event.hash IS NULL THEN RETURN NULL;END IF;
 SELECT count(*) INTO selected_n FROM public.domain_event WHERE tenant_id=p_event.tenant_id AND chain_seq=p_event.chain_seq;
 IF selected_n<>1 THEN RETURN NULL;END IF;
 IF p_event.chain_seq>1 THEN
  SELECT count(*) INTO n FROM public.domain_event WHERE tenant_id=p_event.tenant_id AND chain_seq=p_event.chain_seq-1;
  IF n<>1 THEN RETURN NULL;END IF;
  SELECT chain_seq,hash INTO prior_seq,prior_hash FROM public.domain_event
   WHERE tenant_id=p_event.tenant_id AND chain_seq=p_event.chain_seq-1;
 END IF;
 IF p_event.prev_hash IS DISTINCT FROM coalesce(prior_hash,'GENESIS')
  OR p_event.hash IS DISTINCT FROM app.domain_event_hash(p_event.prev_hash,p_event.tenant_id,p_event.chain_seq,
   p_event.aggregate_type,p_event.aggregate_id,p_event.event_type,p_event.actor_type::text,p_event.actor_id,
   p_event.subject_employment_id,p_event.payload) THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('armed',true,'priorSeq',prior_seq,'priorHash',prior_hash);
END

DECLARE candidate jsonb;
BEGIN
 IF p_preimage IS NULL THEN RETURN false;END IF;
 candidate:=app._domain_event_preimage_for(p_event);
 RETURN candidate IS NOT NULL AND candidate IS NOT DISTINCT FROM p_preimage
  AND p_scope IS NOT DISTINCT FROM app._bank_json_hash(
   to_jsonb(p_event)-ARRAY['id','sequence','occurred_at','payload','chain_seq','prev_hash','hash']);
END

DECLARE actual_hash text;actual_before text;erasure boolean:=false;
BEGIN
 IF TG_RELID<>'app.assistant_own_leave_review'::regclass OR TG_LEVEL<>'ROW' THEN
  RAISE EXCEPTION 'Bank review fence unavailable' USING ERRCODE='42501';END IF;
 -- Once armed, deleting/recreating or retiring/rearming the pending receipt cannot launder its
 -- native-derived baseline. Only the exact initial completion delta may cross this boundary.
 IF OLD.action_kind='employees.bank.maintain' AND OLD.bank_retained_version=1
  AND OLD.state='awaiting_confirmation' AND OLD.bank_retained_root_xid=pg_current_xact_id() THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Bank armed review immutable' USING ERRCODE='42501';END IF;
  IF NEW.state IS DISTINCT FROM 'completed' OR NEW.receipt_event_id IS NULL
   OR to_jsonb(NEW) IS DISTINCT FROM (to_jsonb(OLD)||jsonb_build_object('state','completed',
    'intent_digest',NULL,'reviewed_digest',NULL,'receipt_event_id',NEW.receipt_event_id)) THEN
   RAISE EXCEPTION 'Bank armed review immutable' USING ERRCODE='42501';END IF;
 END IF;
 IF OLD.action_kind='employees.bank.maintain' AND OLD.bank_retained_version=1 AND OLD.state='completed' THEN
  IF TG_OP='DELETE' THEN
   IF NOT app._bank_review_cascade_admitted(OLD::app.assistant_own_leave_review) THEN RAISE EXCEPTION 'Bank completed identity immutable' USING ERRCODE='42501';END IF;
   IF TG_WHEN='BEFORE' THEN RETURN OLD;END IF;RETURN NULL;
  END IF;
  IF OLD.bank_retained_root_xid=pg_current_xact_id() THEN
   RAISE EXCEPTION 'Bank completed command closed until commit' USING ERRCODE='42501';END IF;
  IF TG_OP='UPDATE' THEN
   IF ROW(NEW.id,NEW.action_kind,NEW.tenant_id,NEW.user_id,NEW.person_id,NEW.employment_id,NEW.company_id,
     NEW.decision_subject_person_id,NEW.receipt_subject_kind,NEW.receipt_subject_id,NEW.receipt_event_id,
     NEW.state,NEW.created_at,NEW.expires_at,NEW.bank_retained_version)
    IS DISTINCT FROM ROW(OLD.id,OLD.action_kind,OLD.tenant_id,OLD.user_id,OLD.person_id,OLD.employment_id,OLD.company_id,
     OLD.decision_subject_person_id,OLD.receipt_subject_kind,OLD.receipt_subject_id,OLD.receipt_event_id,
     OLD.state,OLD.created_at,OLD.expires_at,OLD.bank_retained_version) THEN
    RAISE EXCEPTION 'Bank completed identity immutable' USING ERRCODE='42501';END IF;
   IF ROW(NEW.bank_retained_prepare_hash,NEW.bank_before_hash,NEW.bank_after_hash,NEW.bank_event_payload_hash,NEW.bank_event_scope_hash,NEW.bank_retained_root_xid,NEW.bank_audit_preimage)
    IS DISTINCT FROM ROW(OLD.bank_retained_prepare_hash,OLD.bank_before_hash,OLD.bank_after_hash,OLD.bank_event_payload_hash,OLD.bank_event_scope_hash,OLD.bank_retained_root_xid,OLD.bank_audit_preimage) THEN
    SELECT EXISTS(SELECT 1 FROM app.assistant_review_erasure_intent i WHERE i.xact_id=pg_current_xact_id()
     AND i.tenant_id=OLD.tenant_id AND i.user_id=app.current_user_id() AND OLD.id=ANY(i.review_ids)) INTO erasure;
    IF NOT erasure OR NEW.bank_retained_prepare_hash IS NOT NULL OR NEW.bank_before_hash IS NOT NULL OR NEW.bank_after_hash IS NOT NULL OR NEW.bank_event_payload_hash IS NOT NULL OR NEW.bank_event_scope_hash IS NOT NULL OR NEW.bank_retained_root_xid IS NOT NULL OR NEW.bank_audit_preimage IS NOT NULL THEN
     RAISE EXCEPTION 'Bank private proof erasure unavailable' USING ERRCODE='42501';END IF;
   END IF;
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN IF TG_WHEN='BEFORE' THEN RETURN OLD;END IF;RETURN NULL;END IF;
 IF NEW.action_kind='employees.bank.maintain' AND NEW.bank_retained_version=1 THEN
  IF OLD.bank_retained_version=1 AND NEW.bank_retained_version IS DISTINCT FROM OLD.bank_retained_version THEN
   RAISE EXCEPTION 'Bank proof version immutable' USING ERRCODE='42501';END IF;
  IF NEW.state IN('discarded','expired','refused') THEN
   IF TG_WHEN='BEFORE' THEN NEW.bank_retained_prepare_hash:=NULL;NEW.bank_before_hash:=NULL;NEW.bank_after_hash:=NULL;NEW.bank_event_payload_hash:=NULL;NEW.bank_event_scope_hash:=NULL;NEW.bank_retained_root_xid:=NULL;NEW.bank_audit_preimage:=NULL;
   ELSIF NEW.bank_retained_prepare_hash IS NOT NULL OR NEW.bank_before_hash IS NOT NULL OR NEW.bank_after_hash IS NOT NULL OR NEW.bank_event_payload_hash IS NOT NULL OR NEW.bank_event_scope_hash IS NOT NULL OR NEW.bank_retained_root_xid IS NOT NULL OR NEW.bank_audit_preimage IS NOT NULL THEN
    RAISE EXCEPTION 'Bank terminal private proof unavailable' USING ERRCODE='42501';END IF;
  ELSIF NEW.state='awaiting_confirmation' THEN
   IF NEW.bank_audit_preimage IS DISTINCT FROM OLD.bank_audit_preimage
    OR NEW.bank_retained_root_xid IS DISTINCT FROM OLD.bank_retained_root_xid THEN
    IF OLD.bank_retained_root_xid IS NOT NULL OR OLD.bank_audit_preimage IS NOT NULL
     OR NEW.bank_retained_root_xid IS DISTINCT FROM pg_current_xact_id()
     OR NEW.bank_audit_preimage IS DISTINCT FROM app._domain_event_next(NEW.tenant_id,true) THEN
     RAISE EXCEPTION 'Bank audit preimage immutable' USING ERRCODE='42501';END IF;
   END IF;
   IF OLD.bank_retained_version=1 AND ROW(NEW.bank_retained_prepare_hash,NEW.bank_before_hash,NEW.bank_after_hash,NEW.bank_event_payload_hash,NEW.bank_event_scope_hash) IS DISTINCT FROM ROW(OLD.bank_retained_prepare_hash,OLD.bank_before_hash,OLD.bank_after_hash,OLD.bank_event_payload_hash,OLD.bank_event_scope_hash) THEN
    RAISE EXCEPTION 'Bank prepared source immutable' USING ERRCODE='42501';END IF;
   IF OLD.bank_retained_version IS DISTINCT FROM 1 OR NEW.bank_retained_root_xid IS DISTINCT FROM OLD.bank_retained_root_xid THEN
    SELECT app._bank_retained_hash(q),app._bank_full_hash(q) INTO actual_hash,actual_before FROM public.employee_statutory_my q
     WHERE q.tenant_id=NEW.tenant_id AND q.person_id=NEW.decision_subject_person_id;
    IF NEW.bank_retained_prepare_hash IS NULL OR NEW.bank_retained_prepare_hash IS DISTINCT FROM actual_hash OR NEW.bank_before_hash IS DISTINCT FROM actual_before
     OR (NEW.bank_retained_root_xid IS NOT NULL AND NEW.bank_retained_root_xid<>pg_current_xact_id()) THEN
     RAISE EXCEPTION 'Bank retained source changed' USING ERRCODE='42501';END IF;
   END IF;
  ELSIF NEW.state='completed' AND OLD.state='awaiting_confirmation' THEN
   IF NEW.bank_retained_root_xid IS DISTINCT FROM pg_current_xact_id()
    OR ROW(NEW.bank_retained_version,NEW.bank_retained_prepare_hash,NEW.bank_retained_root_xid,NEW.bank_audit_preimage)
     IS DISTINCT FROM ROW(OLD.bank_retained_version,OLD.bank_retained_prepare_hash,OLD.bank_retained_root_xid,OLD.bank_audit_preimage) THEN
    RAISE EXCEPTION 'Bank completion arm unavailable' USING ERRCODE='42501';END IF;
  END IF;
 END IF;
 IF OLD.bank_retained_version=1 AND (NEW.action_kind IS DISTINCT FROM OLD.action_kind
  OR NEW.bank_retained_version IS DISTINCT FROM 1) THEN
  RAISE EXCEPTION 'Bank proof binding immutable' USING ERRCODE='42501';END IF;
 IF TG_WHEN='BEFORE' THEN RETURN NEW;END IF;RETURN NULL;
END

DECLARE r app.assistant_own_leave_review%ROWTYPE;q public.employee_statutory_my%ROWTYPE;
 expected_parent jsonb;actual_parent jsonb;expected_body jsonb;actual_body jsonb;audit_pre jsonb;
BEGIN
 PERFORM app._bank_review_interval();
 SELECT * INTO r FROM app.assistant_own_leave_review WHERE id=p_id AND tenant_id=app.current_tenant_id()
  AND user_id=app.current_user_id() AND action_kind='employees.bank.maintain' FOR UPDATE NOWAIT;
 IF NOT FOUND OR r.state<>'awaiting_confirmation' OR r.bank_retained_version IS DISTINCT FROM 1
  OR r.bank_retained_prepare_hash IS NULL OR clock_timestamp()>=r.expires_at
  OR (r.bank_retained_root_xid IS NOT NULL AND r.bank_retained_root_xid IS DISTINCT FROM pg_current_xact_id()) THEN
  RAISE EXCEPTION 'Bank review arm unavailable' USING ERRCODE='42501';END IF;
 PERFORM app._assistant_assigned_review_binding(r.action_kind,r.person_id,r.employment_id,r.company_id,r.decision_subject_person_id,r.receipt_subject_id);
 PERFORM app.assistant_bank_maintenance_scope(r.employment_id);
 audit_pre:=app._domain_event_next(r.tenant_id,true);
 IF r.bank_retained_root_xid=pg_current_xact_id() AND r.bank_audit_preimage IS DISTINCT FROM audit_pre THEN
  RAISE EXCEPTION 'Bank audit preimage immutable' USING ERRCODE='42501';END IF;
 SELECT * INTO q FROM public.employee_statutory_my WHERE tenant_id=r.tenant_id AND person_id=r.decision_subject_person_id FOR UPDATE NOWAIT;
 IF NOT FOUND OR app._bank_full_hash(q) IS DISTINCT FROM r.bank_before_hash
  OR app._bank_retained_hash(q) IS DISTINCT FROM r.bank_retained_prepare_hash
  OR app._bank_json_hash(app._bank_event_scope(q.tenant_id,q.person_id,q.id,r.user_id)) IS DISTINCT FROM r.bank_event_scope_hash THEN
  RAISE EXCEPTION 'Bank retained source changed' USING ERRCODE='42501';END IF;
 SELECT to_jsonb(c) INTO expected_body FROM app.assistant_own_leave_review_content c WHERE c.action_id=r.id;
 IF expected_body IS NULL THEN RAISE EXCEPTION 'Bank review arm unavailable' USING ERRCODE='42501';END IF;
 expected_parent:=to_jsonb(r)||jsonb_build_object('bank_retained_root_xid',pg_current_xact_id(),'bank_audit_preimage',audit_pre);
 IF r.bank_retained_root_xid IS DISTINCT FROM pg_current_xact_id() THEN
  UPDATE app.assistant_own_leave_review SET bank_retained_root_xid=pg_current_xact_id(),bank_audit_preimage=audit_pre WHERE id=r.id;
 END IF;
 -- Re-read after every arm callback. Do not let later completion bless a newly tainted baseline.
 SELECT to_jsonb(a) INTO actual_parent FROM app.assistant_own_leave_review a WHERE a.id=r.id;
 SELECT to_jsonb(c) INTO actual_body FROM app.assistant_own_leave_review_content c WHERE c.action_id=r.id;
 IF actual_parent IS DISTINCT FROM expected_parent OR actual_body IS DISTINCT FROM expected_body THEN
  RAISE EXCEPTION 'Bank armed custody changed' USING ERRCODE='42501';END IF;
 PERFORM app._assistant_leave_decision_login();
 IF app.current_tenant_id() IS DISTINCT FROM r.tenant_id OR app.current_user_id() IS DISTINCT FROM r.user_id
  OR app.principal_snapshot_current() IS NOT TRUE THEN RAISE EXCEPTION 'Bank review arm unavailable' USING ERRCODE='42501';END IF;
 PERFORM app._assistant_assigned_review_binding(r.action_kind,r.person_id,r.employment_id,r.company_id,r.decision_subject_person_id,r.receipt_subject_id);
 PERFORM app.assistant_bank_maintenance_scope(r.employment_id);
 SELECT * INTO q FROM public.employee_statutory_my WHERE tenant_id=r.tenant_id AND person_id=r.decision_subject_person_id FOR UPDATE NOWAIT;
 IF NOT FOUND OR app._bank_full_hash(q) IS DISTINCT FROM r.bank_before_hash
  OR app._bank_retained_hash(q) IS DISTINCT FROM r.bank_retained_prepare_hash
  OR app._bank_json_hash(app._bank_event_scope(q.tenant_id,q.person_id,q.id,r.user_id)) IS DISTINCT FROM r.bank_event_scope_hash
  OR app._domain_event_next(r.tenant_id,true) IS DISTINCT FROM audit_pre THEN
  RAISE EXCEPTION 'Bank retained source changed' USING ERRCODE='42501';END IF;
 IF clock_timestamp()>=r.expires_at THEN RAISE EXCEPTION 'Bank completion deadline unavailable' USING ERRCODE='42501';END IF;
END

DECLARE r app.assistant_own_leave_review%ROWTYPE;
BEGIN
 FOR r IN SELECT q.* FROM app.assistant_own_leave_review q WHERE q.action_kind='employees.bank.maintain'
  AND q.bank_retained_version=1 AND q.state='awaiting_confirmation'
  AND q.bank_retained_root_xid=pg_current_xact_id() AND q.bank_audit_preimage IS NOT NULL LOOP
  -- Arm already owns this exact native key. Reentrant NOWAIT cannot add a blocking lock inversion.
  IF app._domain_event_next(r.tenant_id,true) IS DISTINCT FROM r.bank_audit_preimage THEN
   RAISE EXCEPTION 'Bank audit decision changed before native INSERT' USING ERRCODE='42501';END IF;
 END LOOP;
END

DECLARE pre jsonb;head bigint;
BEGIN
 PERFORM app._bank_audit_owner_frame_guard();
 PERFORM app._assistant_catalogue_audit_owner_frame_guard();
 IF current_setting('transaction_isolation')='read committed' AND NOT app._domain_event_chain_key_held(NEW.tenant_id) THEN
  SELECT chain_seq INTO head FROM public.domain_event
   WHERE tenant_id=NEW.tenant_id AND chain_seq IS NOT NULL ORDER BY chain_seq DESC LIMIT 1;
  IF head IS NOT NULL THEN
   NEW.chain_seq:=NULL;NEW.prev_hash:=NULL;NEW.hash:=NULL;
   INSERT INTO app.domain_event_chain_pending(event_id,tenant_id,sequence) VALUES(NEW.id,NEW.tenant_id,NEW.sequence);
   RETURN NEW;
  END IF;
  IF current_setting('app.audit_hash_chain',true) IS DISTINCT FROM 'on'
   AND NOT EXISTS(SELECT 1 FROM public.tenant_setting WHERE tenant_id=NEW.tenant_id AND key='audit.hash_chain_enabled' AND value='true'::jsonb) THEN
   INSERT INTO app.domain_event_chain_pending(event_id,tenant_id,sequence) VALUES(NEW.id,NEW.tenant_id,NEW.sequence);
   RETURN NEW;
  END IF;
 END IF;
 pre:=app._domain_event_next(NEW.tenant_id);
 IF NOT (pre->>'armed')::boolean THEN RETURN NEW;END IF;
 NEW.chain_seq:=coalesce((pre->>'priorSeq')::bigint,0)+1;
 NEW.prev_hash:=coalesce(pre->>'priorHash','GENESIS');
 NEW.hash:=app.domain_event_hash(NEW.prev_hash,NEW.tenant_id,NEW.chain_seq,NEW.aggregate_type,
  NEW.aggregate_id,NEW.event_type,NEW.actor_type::text,NEW.actor_id,NEW.subject_employment_id,NEW.payload);
 RETURN NEW;
END

BEGIN
 IF TG_RELID<>'app.assistant_own_leave_review'::regclass OR TG_OP NOT IN('INSERT','UPDATE') THEN
  RAISE EXCEPTION 'Catalogue audit guard unavailable' USING ERRCODE='42501';END IF;
 -- Foreign kinds remain owned by their named NULL CHECK, including JSON null poison.
 IF NEW.action_kind NOT IN('org.position.archive','org.department.archive','org.employee_id_template.status') THEN
  IF TG_OP='INSERT' THEN IF TG_WHEN='BEFORE' THEN RETURN NEW;ELSE RETURN NULL;END IF;
  ELSIF OLD.action_kind NOT IN('org.position.archive','org.department.archive','org.employee_id_template.status') THEN
   IF TG_WHEN='BEFORE' THEN RETURN NEW;ELSE RETURN NULL;END IF;
  END IF;
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.catalogue_audit_preimage IS NOT NULL THEN RAISE EXCEPTION 'Catalogue audit preimage immutable' USING ERRCODE='42501';END IF;
 ELSIF NEW.catalogue_audit_preimage IS DISTINCT FROM OLD.catalogue_audit_preimage THEN
  IF OLD.action_kind IN('org.position.archive','org.department.archive','org.employee_id_template.status')
   AND NEW.action_kind=OLD.action_kind AND OLD.state='awaiting_confirmation' AND NEW.state=OLD.state
   AND OLD.catalogue_native_phase IS NULL AND OLD.catalogue_native_root IS NULL AND OLD.catalogue_native_event IS NULL AND OLD.catalogue_native_tid IS NULL
   AND OLD.catalogue_audit_preimage IS NULL AND NEW.catalogue_native_phase='armed' AND NEW.catalogue_native_root=pg_current_xact_id()
   AND NEW.catalogue_native_event IS NULL AND NEW.catalogue_native_tid IS NULL
   AND NEW.catalogue_audit_preimage IS NOT DISTINCT FROM app._domain_event_next(OLD.tenant_id,true) THEN NULL;
  ELSIF OLD.state<>'completed' AND NEW.state<>'completed' AND NEW.catalogue_audit_preimage IS NULL
   AND NEW.catalogue_native_phase IS NULL AND NEW.catalogue_native_root IS NULL AND NEW.catalogue_native_event IS NULL AND NEW.catalogue_native_tid IS NULL
   AND NOT EXISTS(SELECT 1 FROM app.assistant_own_leave_review_content WHERE action_id=OLD.id) THEN NULL;
  ELSE RAISE EXCEPTION 'Catalogue audit preimage immutable' USING ERRCODE='42501';END IF;
 END IF;
 IF TG_WHEN='BEFORE' THEN RETURN NEW;END IF;RETURN NULL;
END

DECLARE r app.assistant_own_leave_review%ROWTYPE;expected jsonb;actual jsonb;root xid8:=pg_current_xact_id();audit_pre jsonb;
BEGIN
 SELECT * INTO r FROM app.assistant_own_leave_review WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR r.action_kind NOT IN('org.position.archive','org.department.archive','org.employee_id_template.status')
  OR r.state<>'awaiting_confirmation' OR clock_timestamp()>=r.expires_at THEN RAISE EXCEPTION 'Catalogue interval unavailable' USING ERRCODE='42501';END IF;
 IF p_phase='armed' THEN
  IF r.catalogue_native_phase IS NOT NULL OR p_tid IS NOT NULL OR p_event IS NOT NULL THEN RAISE EXCEPTION 'Catalogue interval unavailable' USING ERRCODE='42501';END IF;
 ELSIF p_phase='written' THEN
  IF r.catalogue_native_phase IS DISTINCT FROM 'armed' OR r.catalogue_native_root IS DISTINCT FROM root OR p_tid IS NULL OR p_event IS NOT NULL THEN RAISE EXCEPTION 'Catalogue interval unavailable' USING ERRCODE='42501';END IF;
 ELSIF p_phase='recorded' THEN
  IF r.catalogue_native_phase IS DISTINCT FROM 'written' OR r.catalogue_native_root IS DISTINCT FROM root OR p_tid IS DISTINCT FROM r.catalogue_native_tid OR p_event IS NULL THEN RAISE EXCEPTION 'Catalogue interval unavailable' USING ERRCODE='42501';END IF;
 ELSE RAISE EXCEPTION 'Catalogue interval unavailable' USING ERRCODE='42501';END IF;
 IF p_phase='armed' THEN
  -- Pinned shared V6 canonical owner; never substitute a local algorithm or caller JSON.
  audit_pre:=app._domain_event_next(r.tenant_id,true);
 ELSE audit_pre:=r.catalogue_audit_preimage;END IF;
 IF audit_pre IS NULL THEN RAISE EXCEPTION 'Catalogue audit preimage unavailable' USING ERRCODE='42501';END IF;
 expected:=to_jsonb(r)||jsonb_build_object('catalogue_native_phase',p_phase,'catalogue_native_root',root,'catalogue_native_tid',p_tid,'catalogue_native_event',p_event,'catalogue_audit_preimage',audit_pre);
 UPDATE app.assistant_own_leave_review SET catalogue_native_phase=p_phase,catalogue_native_root=root,catalogue_native_tid=p_tid,catalogue_native_event=p_event,catalogue_audit_preimage=audit_pre WHERE id=r.id;
 SELECT to_jsonb(saved) INTO actual FROM app.assistant_own_leave_review saved WHERE id=r.id;
 IF actual IS DISTINCT FROM expected OR NOT EXISTS(SELECT 1 FROM app.assistant_own_leave_review_content WHERE action_id=r.id) THEN RAISE EXCEPTION 'Catalogue interval postimage changed' USING ERRCODE='42501';END IF;
 IF p_phase='armed' AND app._domain_event_next(r.tenant_id,true) IS DISTINCT FROM audit_pre THEN
  RAISE EXCEPTION 'Catalogue audit preimage changed while arming' USING ERRCODE='42501';END IF;
END

DECLARE native_ok boolean;saved app.assistant_own_leave_review%ROWTYPE;actual_event public.domain_event%ROWTYPE;candidate jsonb;
BEGIN
 -- Only call this after native INSERT/appendEvent RETURNS. It is not an AFTER INSERT witness.
 native_ok:=(SELECT EXISTS(SELECT 1 FROM app.assistant_own_leave_review r JOIN public.domain_event e ON e.id=r.catalogue_native_event AND e.tenant_id=r.tenant_id
 WHERE r.id=p_id AND r.catalogue_native_root=pg_current_xact_id() AND r.catalogue_native_phase IN('recorded','completed')
 AND r.user_id=app.current_user_id() AND e.actor_type='user' AND e.actor_id=r.user_id AND e.subject_employment_id IS NULL
 AND e.aggregate_id=r.receipt_subject_id AND e.xmin=pg_current_xact_id()::xid AND e.occurred_at=transaction_timestamp()
 AND CASE r.action_kind
 WHEN 'org.position.archive' THEN EXISTS(SELECT 1 FROM public.position p WHERE p.id=r.receipt_subject_id AND p.tenant_id=r.tenant_id AND p.company_id=r.company_id
  AND p.ctid=r.catalogue_native_tid AND p.xmin=pg_current_xact_id()::xid AND(p.archived_at IS NOT NULL)=r.position_archive_desired
  AND e.aggregate_type='position' AND e.event_type='position.updated' AND e.payload=jsonb_build_object('title',p.title,'archived',r.position_archive_desired))
 WHEN 'org.department.archive' THEN EXISTS(SELECT 1 FROM public.department p WHERE p.id=r.receipt_subject_id AND p.tenant_id=r.tenant_id AND p.company_id=r.company_id
  AND p.ctid=r.catalogue_native_tid AND p.xmin=pg_current_xact_id()::xid AND(p.archived_at IS NOT NULL)=r.department_archive_desired
  AND e.aggregate_type='department' AND e.event_type='department.updated' AND e.payload=jsonb_build_object('name',p.name,'archived',r.department_archive_desired))
 WHEN 'org.employee_id_template.status' THEN EXISTS(SELECT 1 FROM public.employee_id_config p WHERE p.id=r.receipt_subject_id AND p.tenant_id=r.tenant_id AND p.company_id=r.company_id
  AND p.ctid=r.catalogue_native_tid AND p.xmin=pg_current_xact_id()::xid AND p.status=r.employee_id_template_desired_status
  AND e.aggregate_type='employee-id-config' AND e.event_type=CASE r.employee_id_template_desired_status WHEN 'active' THEN 'employee-id-config.activated' ELSE 'employee-id-config.deactivated' END
  AND e.payload=jsonb_build_object('status',r.employee_id_template_desired_status)) ELSE false END));
 IF native_ok IS NOT TRUE THEN RETURN false;END IF;
 SELECT * INTO saved FROM app.assistant_own_leave_review WHERE id=p_id;
 IF NOT FOUND OR saved.catalogue_audit_preimage IS NULL THEN RETURN false;END IF;
 SELECT * INTO actual_event FROM public.domain_event WHERE id=saved.catalogue_native_event AND tenant_id=saved.tenant_id;
 IF NOT FOUND THEN RETURN false;END IF;
 -- Candidate is qualified by the reviewed canonical owner, NOT used as its own expected fact.
 -- Exact V6 private decoder is root-cleared; this new purpose integration still needs review.
 candidate:=app._domain_event_preimage_for(actual_event);
 RETURN candidate IS NOT NULL AND candidate IS NOT DISTINCT FROM saved.catalogue_audit_preimage;
END
